/// Version of this map, exposed in input register [`MAP_VERSION_ADDR`].
pub const MAP_VERSION: u16 = 2;

/// Where the map version lives. Unchanged from version 1 on purpose.
pub const MAP_VERSION_ADDR: u16 = 14;

