pub const NODE_POWER_BIT_BASE: u16 = 100;
/// First discrete input of the per-node host bits.
pub const NODE_HOST_BIT_BASE: u16 = 200;

/// First input register of the probes.
pub const PROBE_BASE: u16 = 0;
/// Input register of the board temperature.
pub const BOARD_TEMP_ADDR: u16 = 8;
/// Input register of the controller input voltage.
pub const VIN_ADDR: u16 = 9;
/// First input register of the uptime pair.
pub const UPTIME_ADDR: u16 = 10;
/// Input register of the firmware version.
pub const FW_ADDR: u16 = 12;
/// Input register of the fault bitmap.
pub const FAULTS_ADDR: u16 = 13;
/// Input register of the planes-present bitmap.
pub const PLANES_PRESENT_ADDR: u16 = 15;
/// Input register of the present-node count.
pub const NODE_COUNT_ADDR: u16 = 16;

/// First input register of the per-node blocks.
pub const NODE_BASE: u16 = 100;
/// Input registers per node.
pub const NODE_STRIDE: u16 = 12;
/// First input register of the per-plane blocks.
pub const PLANE_BASE: u16 = 900;
