pub const PLANE_STRIDE: u16 = 16;

/// Holding register of the `on_all` trigger. Unchanged from version 1.
pub const ON_ALL_ADDR: u16 = 8;
/// Holding register of the last command result. Unchanged from version 1.
pub const LAST_RESULT_ADDR: u16 = 9;
/// First holding register of the per-node command words.
pub const NODE_CMD_BASE: u16 = 100;
/// First holding register of the per-plane command words.
pub const PLANE_CMD_BASE: u16 = 200;
/// First coil of the per-node rail mirrors.
pub const NODE_COIL_BASE: u16 = 100;

/// Node command words (holding register [`NODE_CMD_BASE`] + id - 1).
pub mod cmd_word {
    /// No command / cleared.
    pub const NONE: u16 = 0;
    /// `on`.
    pub const ON: u16 = 1;
    /// `off` (escalates like the MQTT command).
    pub const OFF: u16 = 2;
    /// `force_off`.
    pub const FORCE_OFF: u16 = 3;
    /// `reset`.
    pub const RESET: u16 = 4;
    /// `cycle`.
    pub const CYCLE: u16 = 5;
    /// `power_on`: the rail only.
    pub const POWER_ON: u16 = 6;
    /// `power_off`: the rail only.
    pub const POWER_OFF: u16 = 7;
    /// `clear_latch`.
    pub const CLEAR_LATCH: u16 = 8;
}

/// Plane command words (holding register [`PLANE_CMD_BASE`] + plane).
pub mod plane_cmd_word {
    /// No command / cleared.
    pub const NONE: u16 = 0;
    /// `plane_reboot`.
    pub const REBOOT: u16 = 1;
    /// `unit_reset` of unit 0; unit *u* is `UNIT_RESET + u`.
    pub const UNIT_RESET: u16 = 2;
}

/// Bits of the per-node faults register (node block offset 10).
pub mod node_fault_bits {
    /// No module in the slot, or no unit board on that half of the
    /// chain. An absent node reads 0 everywhere else.
    pub const ABSENT: u16 = 1 << 0;
    /// The slot's overvoltage latch is set.
    pub const OV_LATCHED: u16 = 1 << 1;
    /// The slot's power limit tripped.
    pub const POWER_LIMIT: u16 = 1 << 2;
    /// The plane gave up retrying the hot-swap.
    pub const RETRY_LIMIT: u16 = 1 << 3;
    /// The unit's own hot-swap latched off.
    pub const UNIT_LATCHED_OFF: u16 = 1 << 4;
    /// The plane's LED-against-rail cross-check disagrees.
    pub const CROSS_CHECK: u16 = 1 << 5;
    /// A sequence is running on the slot.
    pub const BUSY: u16 = 1 << 6;
}

/// Bits of the per-plane flags register (plane block offset 0).
pub mod plane_flag_bits {
    /// The plane answers.
    pub const PRESENT: u16 = 1 << 0;
    /// A sequence runs on one of its slots.
    pub const SEQUENCE_RUNNING: u16 = 1 << 1;
    /// It holds unacknowledged events.
    pub const EVENTS_PENDING: u16 = 1 << 2;
    /// It says its intended state is lost.
    pub const INTENDED_STATE_LOST: u16 = 1 << 3;
}

/// Bits of input register [`FAULTS_ADDR`].
pub mod fault_bits {
    /// A plane the controller had found stopped answering.
    pub const PLANE_LOST: u16 = 1 << 0;
    /// A node is in fault (ADR 0004 decision 3).
    pub const NODE_FAULT: u16 = 1 << 1;
    /// A configured probe did not answer.
    pub const PROBE_MISSING: u16 = 1 << 2;
    /// VIN outside the configured window.
    pub const VIN: u16 = 1 << 3;
    /// An OTA image is pending validation.
    pub const OTA_PENDING: u16 = 1 << 4;
    /// A config section fell back to its defaults at boot.
    pub const CONFIG_FALLBACK: u16 = 1 << 5;
    /// The broker is configured but not connected.
    pub const MQTT_DOWN: u16 = 1 << 6;
    /// No plane answers at all.
    pub const NO_PLANE: u16 = 1 << 7;
}

/// What register [`LAST_RESULT_ADDR`] reports.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
#[repr(u16)]
pub enum ResultCode {
    /// Nothing has been commanded yet.
    #[default]
    Idle = 0,
    /// The last command finished successfully.
    Ok = 1,
    /// The last command was accepted and is running on a plane.
    Accepted = 2,
    /// The last command was refused.
    Refused = 3,
    /// The last command failed.
    Failed = 4,
    /// The node, unit or plane is not there.
    Absent = 5,
}

impl ResultCode {
    /// Register value.
    pub const fn as_u16(self) -> u16 {
        self as u16
    }

    /// Map a dispatcher ack onto a code.
    ///
    /// The Modbus server only ever sees a [`Reply`]: the plane job
    /// finishes later and nothing on the wire can wait for it, so
    /// `accepted` is the honest answer for a verb that was queued, and
    /// a reader that wants the outcome reads the node's state.
    pub fn of_reply(reply: &Reply) -> Self {
        if reply.ok {
            return match reply.result.as_deref() {
                Some("accepted") => ResultCode::Accepted,
                _ => ResultCode::Ok,
            };
        }
        match reply.error.as_deref() {
            Some(e) if e.starts_with("failed") => ResultCode::Failed,
            Some(e) if e.contains("not present") || e.contains("absent") => ResultCode::Absent,
            _ => ResultCode::Refused,
        }
    }
}

/// Firmware version as the map reports it.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct FwVersion {
    /// Major.
    pub major: u8,
    /// Minor.
    pub minor: u8,
}

impl FwVersion {
    /// Packed `major << 8 | minor`.
    pub const fn as_u16(self) -> u16 {
        ((self.major as u16) << 8) | self.minor as u16
    }
}

/// Which table an entry belongs to.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RegKind {
    /// Function 2, read only, one bit.
    DiscreteInput,
    /// Function 4, read only, 16 bits.
    InputRegister,
    /// Functions 3 / 6 / 16, read and write, 16 bits.
    HoldingRegister,
    /// Functions 1 / 5, read and write, one bit.
    Coil,
}

impl RegKind {
    /// Table name for the documentation.
    pub const fn as_str(self) -> &'static str {
        match self {
            RegKind::DiscreteInput => "Discrete inputs",
            RegKind::InputRegister => "Input registers",
            RegKind::HoldingRegister => "Holding registers",
            RegKind::Coil => "Coils",
        }
    }
}

/// Read / write permission of an entry.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Access {
    /// Read only.
    R,
    /// Read and write.
    Rw,
}

impl Access {
    /// Documentation string.
    pub const fn as_str(self) -> &'static str {
        match self {
            Access::R => "r",
            Access::Rw => "rw",
        }
    }
}

/// One fixed row of the map.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RegEntry {
    /// Which table.
    pub kind: RegKind,
    /// Address inside that table.
    pub addr: u16,
    /// Short identifier.
    pub name: &'static str,
    /// What it means.
    pub meaning: &'static str,
    /// Unit and scaling.
    pub scale: &'static str,
    /// Permission.
    pub access: Access,
}

const fn di(addr: u16, name: &'static str, meaning: &'static str) -> RegEntry {
    RegEntry {
        kind: RegKind::DiscreteInput,
        addr,
        name,
        meaning,
        scale: "0/1",
        access: Access::R,
    }
}

const fn ir(addr: u16, name: &'static str, meaning: &'static str, scale: &'static str) -> RegEntry {
    RegEntry {
        kind: RegKind::InputRegister,
        addr,
        name,
        meaning,
        scale,
        access: Access::R,
    }
}

const fn hr(addr: u16, name: &'static str, meaning: &'static str, scale: &'static str) -> RegEntry {
    RegEntry {
        kind: RegKind::HoldingRegister,
        addr,
        name,
        meaning,
        scale,
        access: Access::Rw,
    }
}

