/// One field of a repeated block.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BlockField {
    /// Offset inside the block.
    pub offset: u16,
    /// Short identifier.
    pub name: &'static str,
    /// What it means.
    pub meaning: &'static str,
    /// Unit and scaling.
    pub scale: &'static str,
}

const fn field(
    offset: u16,
    name: &'static str,
    meaning: &'static str,
    scale: &'static str,
) -> BlockField {
    BlockField {
        offset,
        name,
        meaning,
        scale,
    }
}

/// A repeated block: one per node, or one per plane.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Block {
    /// Which table.
    pub kind: RegKind,
    /// Address of the first block.
    pub base: u16,
    /// Addresses per block.
    pub stride: u16,
    /// How many blocks there are.
    pub count: u16,
    /// What one block is about ("node", "plane").
    pub of: &'static str,
    /// Whether the index starts at 0 or at 1.
    pub first_index: u16,
    /// The fields, in offset order. Empty for a one-register block.
    pub fields: &'static [BlockField],
    /// Permission.
    pub access: Access,
    /// What one register means, for a one-register block.
    pub meaning: &'static str,
    /// Unit and scaling, for a one-register block.
    pub scale: &'static str,
}

