/// Look one fixed entry up.
pub fn entry(kind: RegKind, addr: u16) -> Option<&'static RegEntry> {
    MAP.iter().find(|e| e.kind == kind && e.addr == addr)
}

/// The block an address falls in, with the index and the offset.
pub fn block_of(kind: RegKind, addr: u16) -> Option<(&'static Block, u16, u16)> {
    for block in BLOCKS {
        if block.kind != kind || addr < block.base {
            continue;
        }
        let span = block.stride * block.count;
        if addr >= block.base + span {
            continue;
        }
        let rel = addr - block.base;
        let index = rel / block.stride + block.first_index;
        let offset = rel % block.stride;
        if block.fields.is_empty() || block.fields.iter().any(|f| f.offset == offset) {
            return Some((block, index, offset));
        }
        return None;
    }
    None
}

/// What one address is, as a name: `node7_watts`, `plane1_flags`,
/// `dry_in2`. `None` when the address is not in the map.
pub fn name_of(kind: RegKind, addr: u16) -> Option<String> {
    if let Some(e) = entry(kind, addr) {
        return Some(String::from(e.name));
    }
    let (block, index, offset) = block_of(kind, addr)?;
    let suffix = block
        .fields
        .iter()
        .find(|f| f.offset == offset)
        .map(|f| f.name);
    Some(match (kind, suffix) {
        (_, Some(name)) => format!("{}{index}_{name}", block.of),
        (RegKind::DiscreteInput, None) if block.base == NODE_HOST_BIT_BASE => {
            format!("node{index}_host")
        }
        (RegKind::DiscreteInput, None) => format!("node{index}_power"),
        (RegKind::HoldingRegister, None) => format!("{}{index}_cmd", block.of),
        (_, None) => format!("{}{index}_rail", block.of),
    })
}

/// Why a Modbus write could not be turned into a command.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MapError {
    /// No such register in this table (Modbus exception 2).
    UnknownRegister {
        /// Which table.
        kind: RegKind,
        /// Which address.
        addr: u16,
    },
    /// The register exists but the value means nothing (exception 3).
    BadValue {
        /// Which address.
        addr: u16,
        /// What was written.
        value: u16,
    },
}

impl fmt::Display for MapError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            MapError::UnknownRegister { kind, addr } => {
                write!(f, "no {} at {addr}", kind.as_str())
            }
            MapError::BadValue { addr, value } => {
                write!(f, "value {value} is not valid for register {addr}")
            }
        }
    }
}

