/// The read side of the map: one snapshot, asked one address at a time.
///
/// Sparse by design and cheap to build: it borrows the snapshot rather
/// than rendering 1000 registers into an array nobody reads (the board
/// serves this from a connection thread's stack).
#[derive(Debug, Clone, Copy)]
pub struct Image<'a> {
    /// The snapshot every value comes from.
    pub observed: &'a Observed,
    /// Firmware version for [`FW_ADDR`].
    pub fw: FwVersion,
    /// Fault bitmap for [`FAULTS_ADDR`].
    pub faults: u16,
    /// What the last command word produced.
    pub last_result: ResultCode,
}

impl<'a> Image<'a> {
    /// An image over one snapshot.
    pub const fn new(
        observed: &'a Observed,
        fw: FwVersion,
        faults: u16,
        last_result: ResultCode,
    ) -> Self {
        Image {
            observed,
            fw,
            faults,
            last_result,
        }
    }

    /// One bit, `None` when the address is not in the map.
    pub fn bit(&self, kind: RegKind, addr: u16) -> Option<bool> {
        match kind {
            RegKind::Coil => {
                let node = node_of(NODE_COIL_BASE, addr)?;
                Some(self.observed.node_power(node) == PowerState::On)
            }
            RegKind::DiscreteInput => {
                if (DRY_BASE..DRY_BASE + DRY_COUNT as u16).contains(&addr) {
                    return Some(self.observed.dry((addr - DRY_BASE + 1) as u8) == Some(true));
                }
                if addr == LINK_ADDR {
                    return Some(self.observed.link_up.value);
                }
                if addr == MQTT_ADDR {
                    return Some(self.observed.mqtt_connected.value);
                }
                if let Some(node) = node_of(NODE_POWER_BIT_BASE, addr) {
                    return Some(self.observed.node_power(node) == PowerState::On);
                }
                if let Some(node) = node_of(NODE_HOST_BIT_BASE, addr) {
                    return Some(
                        self.observed.node_host(node) == crate::plane::model::HostState::On,
                    );
                }
                None
            }
            _ => None,
        }
    }

    /// One register, `None` when the address is not in the map.
    pub fn word(&self, kind: RegKind, addr: u16) -> Option<u16> {
        match kind {
            RegKind::InputRegister => self.input(addr),
            RegKind::HoldingRegister => self.holding(addr),
            _ => None,
        }
    }

    fn input(&self, addr: u16) -> Option<u16> {
        let o = self.observed;
        if (PROBE_BASE..PROBE_BASE + PROBE_SLOTS as u16).contains(&addr) {
            let centi = o
                .probe((addr - PROBE_BASE) as usize)
                .and_then(|p| p.centi_c)
                .unwrap_or(TEMP_MISSING);
            return Some(centi as u16);
        }
        match addr {
            BOARD_TEMP_ADDR => Some(o.board_temp.value.unwrap_or(TEMP_MISSING) as u16),
            VIN_ADDR => Some(o.vin_mv.value.unwrap_or(0).min(u32::from(u16::MAX)) as u16),
            UPTIME_ADDR => Some((o.uptime_s.value >> 16) as u16),
            a if a == UPTIME_ADDR + 1 => Some((o.uptime_s.value & 0xffff) as u16),
            FW_ADDR => Some(self.fw.as_u16()),
            FAULTS_ADDR => Some(self.faults),
            MAP_VERSION_ADDR => Some(MAP_VERSION),
            PLANES_PRESENT_ADDR => {
                let mut bits = 0u16;
                for plane in &o.planes {
                    bits |= 1 << plane.plane;
                }
                Some(bits)
            }
            NODE_COUNT_ADDR => Some(o.nodes.iter().filter(|n| n.present).count() as u16),
            _ => self.block_word(addr),
        }
    }

    fn block_word(&self, addr: u16) -> Option<u16> {
        let (block, index, offset) = block_of(RegKind::InputRegister, addr)?;
        if block.base == NODE_BASE {
            return Some(self.node_word(index as NodeId, offset));
        }
        if block.base == PLANE_BASE {
            return Some(self.plane_word(index as u8, offset));
        }
        None
    }

    /// One register of a node block. An absent node reads 0 everywhere
    /// but in its faults word, which carries
    /// [`node_fault_bits::ABSENT`] (ADR 0004 decision 7).
    fn node_word(&self, node: NodeId, offset: u16) -> u16 {
        let Some(n) = self.observed.node(node) else {
            return if offset == 10 {
                node_fault_bits::ABSENT
            } else {
                0
            };
        };
        let t = &n.telemetry;
        match offset {
            0 => u16::from(power_code(n.power)),
            1 => u16::from(host_code(n.host)),
            2 => t.volts,
            3 => t.amps,
            4 => t.watts,
            5 => t.temperature as u16,
            6 => (energy_u32(t.energy_joules) >> 16) as u16,
            7 => (energy_u32(t.energy_joules) & 0xffff) as u16,
            8 => (t.energy_boot_count >> 16) as u16,
            9 => (t.energy_boot_count & 0xffff) as u16,
            10 => n.faults.bits() | if n.busy { node_fault_bits::BUSY } else { 0 },
            11 => (u16::from(n.slot) << 8) | u16::from(t.module_class),
            _ => 0,
        }
    }

    /// One register of a plane block. A plane that does not answer reads
    /// 0 everywhere, flags included.
    fn plane_word(&self, plane: u8, offset: u16) -> u16 {
        let Some(p) = self.observed.plane(plane) else {
            return 0;
        };
        match offset {
            0 => {
                let mut bits = plane_flag_bits::PRESENT;
                if p.sequence_running {
                    bits |= plane_flag_bits::SEQUENCE_RUNNING;
                }
                if p.events_pending {
                    bits |= plane_flag_bits::EVENTS_PENDING;
                }
                if p.intended_state_lost {
                    bits |= plane_flag_bits::INTENDED_STATE_LOST;
                }
                bits
            }
            1 => packed_version(&p.firmware),
            2 => p.bus_volts,
            3 => p.core_temperature as u16,
            4 => u16::from(p.units_present),
            5 => u16::from(p.nodes_present),
            6 => (p.boot_count >> 16) as u16,
            7 => (p.boot_count & 0xffff) as u16,
            8 => (p.uptime_s >> 16) as u16,
            9 => (p.uptime_s & 0xffff) as u16,
            10..=13 => p
                .unit((offset - 10) as u8)
                .map(|u| u.watts)
                .unwrap_or_default(),
            14 => {
                let mut bits = 0u16;
                for unit in &p.units {
                    if unit.latched_off {
                        bits |= 1 << unit.unit;
                    }
                }
                bits
            }
            _ => 0,
        }
    }

    fn holding(&self, addr: u16) -> Option<u16> {
        match addr {
            ON_ALL_ADDR => Some(0),
            LAST_RESULT_ADDR => Some(self.last_result.as_u16()),
            _ => {
                if let Some(node) = node_of(NODE_CMD_BASE, addr) {
                    return Some(u16::from(power_code(self.observed.node_power(node))));
                }
                if plane_of(PLANE_CMD_BASE, addr).is_some() {
                    return Some(0);
                }
                None
            }
        }
    }
}

/// Energy as the two registers carry it: joules, saturating at a u32.
const fn energy_u32(joules: u64) -> u32 {
    if joules > u32::MAX as u64 {
        u32::MAX
    } else {
        joules as u32
    }
}

/// `major << 8 | minor` of a `major.minor.patch` string.
fn packed_version(text: &str) -> u16 {
    let mut parts = text.split('.');
    let major: u8 = parts.next().and_then(|p| p.parse().ok()).unwrap_or(0);
    let minor: u8 = parts.next().and_then(|p| p.parse().ok()).unwrap_or(0);
    (u16::from(major) << 8) | u16::from(minor)
}

/// The node id of an address in a per-node block.
fn node_of(base: u16, addr: u16) -> Option<NodeId> {
    if addr < base || addr >= base + MAX_NODES as u16 {
        return None;
    }
    Some((addr - base + 1) as NodeId)
}

/// The plane number of an address in a per-plane block.
fn plane_of(base: u16, addr: u16) -> Option<u8> {
    if addr < base || addr >= base + MAX_PLANES as u16 {
        return None;
    }
    Some((addr - base) as u8)
}

// ---------------------------------------------------------------------
// Writes
// ---------------------------------------------------------------------

/// Turn a holding-register write into a command.
///
/// `Ok(None)` means the write is accepted and means "nothing to do"
/// (writing 0 to a command word clears it). `id` is the command id the
/// server invents, usually `modbus-<counter>`.
pub fn command_from_holding(addr: u16, value: u16, id: &str) -> Result<Option<Command>, MapError> {
    if addr == ON_ALL_ADDR {
        return match value {
            0 => Ok(None),
            1 => Ok(Some(
                Command::new(id, CommandKind::OnAll).with_target(Target::All),
            )),
            _ => Err(MapError::BadValue { addr, value }),
        };
    }
    if addr == LAST_RESULT_ADDR {
        return Err(MapError::BadValue { addr, value });
    }
    if let Some(node) = node_of(NODE_CMD_BASE, addr) {
        let action = match value {
            cmd_word::NONE => return Ok(None),
            cmd_word::ON => CommandKind::On,
            cmd_word::OFF => CommandKind::Off,
            cmd_word::FORCE_OFF => CommandKind::ForceOff,
            cmd_word::RESET => CommandKind::Reset,
            cmd_word::CYCLE => CommandKind::Cycle,
            cmd_word::POWER_ON => CommandKind::PowerOn,
            cmd_word::POWER_OFF => CommandKind::PowerOff,
            cmd_word::CLEAR_LATCH => CommandKind::ClearLatch,
            _ => return Err(MapError::BadValue { addr, value }),
        };
        return Ok(Some(
            Command::new(id, action).with_target(Target::Node(node)),
        ));
    }
    if let Some(plane) = plane_of(PLANE_CMD_BASE, addr) {
        return match value {
            plane_cmd_word::NONE => Ok(None),
            plane_cmd_word::REBOOT => Ok(Some(
                Command::new(id, CommandKind::PlaneReboot).with_target(Target::Plane(plane)),
            )),
            v if (plane_cmd_word::UNIT_RESET..plane_cmd_word::UNIT_RESET + UNIT_COUNT as u16)
                .contains(&v) =>
            {
                let unit = (v - plane_cmd_word::UNIT_RESET) as u8;
                Ok(Some(
                    Command::new(id, CommandKind::UnitReset)
                        .with_target(Target::Unit { plane, unit }),
                ))
            }
            _ => Err(MapError::BadValue { addr, value }),
        };
    }
    Err(MapError::UnknownRegister {
        kind: RegKind::HoldingRegister,
        addr,
    })
}

/// Turn a coil write into a command: 1 = `on`, 0 = `off`.
pub fn command_from_coil(addr: u16, on: bool, id: &str) -> Result<Option<Command>, MapError> {
    let Some(node) = node_of(NODE_COIL_BASE, addr) else {
        return Err(MapError::UnknownRegister {
            kind: RegKind::Coil,
            addr,
        });
    };
    let action = if on {
        CommandKind::On
    } else {
        CommandKind::Off
    };
    Ok(Some(
        Command::new(id, action).with_target(Target::Node(node)),
    ))
}

/// True when a holding-register write would be accepted, without
/// building the command.
///
/// A multi-register write (function 16) is validated in full before any
/// command runs, so one bad address in the span leaves every node alone;
/// this is the check that makes that cheap. It is
/// [`command_from_holding`] itself, so the two cannot drift apart.
pub fn check_holding(addr: u16, value: u16) -> Result<(), MapError> {
    command_from_holding(addr, value, "").map(|_| ())
}

/// True when a coil write would be accepted. See [`check_holding`].
pub fn check_coil(addr: u16) -> Result<(), MapError> {
    command_from_coil(addr, false, "").map(|_| ())
}

/// Default args a Modbus-born command carries: none. Modbus has no room
/// for `force` or a press duration, so a verb behaves exactly as it
/// would over MQTT with an empty `args`.
pub fn modbus_args() -> Args {
    Args::default()
}

/// Render the map as the Markdown document `firmware/docs/modbus_map.md`.
pub fn render_markdown() -> String {
    let mut s = String::new();
    s.push_str("# Granite controller Modbus map\n\n");
    s.push_str(&format!("Map version: {MAP_VERSION}\n\n"));
    s.push_str(
        "Generated from `granite-core/src/modbus_map.rs` (`render_markdown`). \
Do not edit by hand. Unit id and port are configuration (`sec.modbus`); \
the server is off by default and requires an allow-list.\n\n",
    );
    s.push_str(&format!(
        "A node is a slot on a plane: id = 8 x (plane address - 0x30) + slot + 1, \
so 1-{MAX_NODES} (ADR 0004 decision 2). The map is sparse; every address \
that is not listed answers exception 2, the rev C node registers \
included. The map version stays in input register {MAP_VERSION_ADDR}.\n\n"
    ));
    for kind in [
        RegKind::DiscreteInput,
        RegKind::InputRegister,
        RegKind::HoldingRegister,
        RegKind::Coil,
    ] {
        s.push_str(&format!("## {}\n\n", kind.as_str()));
        let fixed: Vec<&RegEntry> = MAP.iter().filter(|e| e.kind == kind).collect();
        if !fixed.is_empty() {
            s.push_str("| Address | Name | Meaning | Scale | Access |\n");
            s.push_str("|---|---|---|---|---|\n");
            for e in fixed {
                s.push_str(&format!(
                    "| {} | `{}` | {} | {} | {} |\n",
                    e.addr,
                    e.name,
                    e.meaning,
                    e.scale,
                    e.access.as_str()
                ));
            }
            s.push('\n');
        }
        for block in BLOCKS.iter().filter(|b| b.kind == kind) {
            let last = block.first_index + block.count - 1;
            let end = block.base + block.stride * block.count - 1;
            if block.fields.is_empty() {
                s.push_str(&format!(
                    "One address per {} {}-{} at {}..{}: {} ({}, {}).\n\n",
                    block.of,
                    block.first_index,
                    last,
                    block.base,
                    end,
                    block.meaning,
                    block.scale,
                    block.access.as_str()
                ));
                continue;
            }
            s.push_str(&format!(
                "{} registers per {} {}-{}, first block at {}, \
address = {} + {} x ({} - {}) + offset:\n\n",
                block.stride,
                block.of,
                block.first_index,
                last,
                block.base,
                block.base,
                block.stride,
                block.of,
                block.first_index
            ));
            s.push_str("| Offset | Name | Meaning | Scale |\n");
            s.push_str("|---|---|---|---|\n");
            for f in block.fields {
                s.push_str(&format!(
                    "| +{} | `{}` | {} | {} |\n",
                    f.offset, f.name, f.meaning, f.scale
                ));
            }
            s.push('\n');
        }
    }
    s.push_str(&format!(
        "## Fault flags (input register {FAULTS_ADDR})\n\n"
    ));
    s.push_str("| Bit | Meaning |\n|---|---|\n");
    for (bit, meaning) in [
        (fault_bits::PLANE_LOST, "a plane stopped answering"),
        (fault_bits::NODE_FAULT, "a node is in fault"),
        (
            fault_bits::PROBE_MISSING,
            "a configured probe did not answer",
        ),
        (
            fault_bits::VIN,
            "controller input voltage outside its window",
        ),
        (
            fault_bits::OTA_PENDING,
            "an OTA image is pending validation",
        ),
        (
            fault_bits::CONFIG_FALLBACK,
            "a config section fell back to defaults",
        ),
        (fault_bits::MQTT_DOWN, "broker configured but not connected"),
        (fault_bits::NO_PLANE, "no plane answers"),
    ] {
        s.push_str(&format!("| {} | {} |\n", bit.trailing_zeros(), meaning));
    }
    s.push('\n');
    s.push_str("## Node faults (node block offset 10)\n\n");
    s.push_str("| Bit | Meaning |\n|---|---|\n");
    for (bit, meaning) in [
        (node_fault_bits::ABSENT, "no module, or no unit board"),
        (node_fault_bits::OV_LATCHED, "overvoltage latch set"),
        (node_fault_bits::POWER_LIMIT, "power limit tripped"),
        (node_fault_bits::RETRY_LIMIT, "hot-swap retry limit reached"),
        (
            node_fault_bits::UNIT_LATCHED_OFF,
            "the unit board latched its hot-swap off",
        ),
        (node_fault_bits::CROSS_CHECK, "LED / rail cross-check"),
        (node_fault_bits::BUSY, "a sequence is running on the slot"),
    ] {
        s.push_str(&format!("| {} | {} |\n", bit.trailing_zeros(), meaning));
    }
    s.push('\n');
    s.push_str(
        "Writes to a node or plane command word, and to a node coil, become the \
same `Command` the MQTT and HTTP paths use, so the rules are identical: the \
verb is submitted as a plane job, the write itself succeeds, and \
`last_result` says `accepted`. A command for a node, unit or plane that is \
not there is refused at once and `last_result` says `absent`.\n",
    );
    s
}

/// The map version as a string, for the documentation header and `/id`.
pub fn map_version_string() -> String {
    MAP_VERSION.to_string()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_blocks_cover_what_they_say() {
        // Node 1 starts the node block, node 64 ends it.
        assert_eq!(
            name_of(RegKind::InputRegister, NODE_BASE).as_deref(),
            Some("node1_power")
        );
        assert_eq!(
            name_of(RegKind::InputRegister, NODE_BASE + 4).as_deref(),
            Some("node1_watts")
        );
        assert_eq!(
            name_of(
                RegKind::InputRegister,
                NODE_BASE + NODE_STRIDE * (MAX_NODES as u16 - 1)
            )
            .as_deref(),
            Some("node64_power")
        );
        assert_eq!(
            name_of(
                RegKind::InputRegister,
                NODE_BASE + NODE_STRIDE * MAX_NODES as u16
            ),
            None,
            "one past the last node is not in the map"
        );
        assert_eq!(
            name_of(RegKind::InputRegister, PLANE_BASE + 2).as_deref(),
            Some("plane0_bus_volts")
        );
        assert_eq!(
            name_of(RegKind::Coil, NODE_COIL_BASE + 8).as_deref(),
            Some("node9_rail")
        );
        // The rev C node registers are gone, loudly.
        assert_eq!(name_of(RegKind::DiscreteInput, 0), None);
        assert_eq!(name_of(RegKind::HoldingRegister, 0), None);
        assert_eq!(name_of(RegKind::Coil, 0), None);
    }

    #[test]
    fn the_command_words_cover_every_verb() {
        let on = command_from_holding(NODE_CMD_BASE + 2, cmd_word::ON, "m-1")
            .expect("a node word")
            .expect("a command");
        assert_eq!(on.action, CommandKind::On);
        assert_eq!(on.target, Target::Node(3));

        let latch = command_from_holding(NODE_CMD_BASE, cmd_word::CLEAR_LATCH, "m-2")
            .unwrap()
            .unwrap();
        assert_eq!(latch.action, CommandKind::ClearLatch);

        let reboot = command_from_holding(PLANE_CMD_BASE + 1, plane_cmd_word::REBOOT, "m-3")
            .unwrap()
            .unwrap();
        assert_eq!(reboot.action, CommandKind::PlaneReboot);
        assert_eq!(reboot.target, Target::Plane(1));

        let unit = command_from_holding(PLANE_CMD_BASE, plane_cmd_word::UNIT_RESET + 2, "m-4")
            .unwrap()
            .unwrap();
        assert_eq!(unit.action, CommandKind::UnitReset);
        assert_eq!(unit.target, Target::Unit { plane: 0, unit: 2 });

        assert_eq!(
            command_from_holding(NODE_CMD_BASE, 99, "m"),
            Err(MapError::BadValue {
                addr: NODE_CMD_BASE,
                value: 99
            })
        );
        assert!(matches!(
            command_from_holding(0, 1, "m"),
            Err(MapError::UnknownRegister { .. })
        ));
        assert!(
            command_from_holding(NODE_CMD_BASE, cmd_word::NONE, "m")
                .unwrap()
                .is_none()
        );
    }

    #[test]
    fn an_absent_node_reads_zero_with_the_absent_bit() {
        let observed = Observed::new();
        let image = Image::new(&observed, FwVersion::default(), 0, ResultCode::Idle);
        assert_eq!(image.word(RegKind::InputRegister, NODE_BASE), Some(0));
        assert_eq!(
            image.word(RegKind::InputRegister, NODE_BASE + 10),
            Some(node_fault_bits::ABSENT)
        );
        assert_eq!(
            image.word(RegKind::InputRegister, MAP_VERSION_ADDR),
            Some(MAP_VERSION)
        );
        assert_eq!(image.bit(RegKind::Coil, NODE_COIL_BASE), Some(false));
        assert_eq!(image.bit(RegKind::DiscreteInput, 0), None);
        assert_eq!(image.word(RegKind::InputRegister, 17), None);
    }

    #[test]
    fn a_version_string_packs() {
        assert_eq!(packed_version("1.2.3"), 0x0102);
        assert_eq!(packed_version(""), 0);
    }
}
